'use strict';
const $=id=>document.getElementById(id);let current=null,active=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const put=(id,value)=>{$(id).textContent=String(value)};const pause=ms=>new Promise(r=>setTimeout(r,reduced?0:ms));
function normalize(value){const v=value.trim().replace(/^https?:\/\/(www\.)?github\.com\//i,'').replace(/^@/,'').replace(/\/$/,'');return /^(?!-)[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(v)&&!v.includes('--')?v:null}
async function api(path,signal){let response;try{response=await fetch('https://api.github.com'+path,{signal,headers:{Accept:'application/vnd.github+json'}})}catch(e){if(e.name==='AbortError')throw e;throw Error('ارتباط با گیت‌هاب برقرار نشد. اینترنت را بررسی کن و دوباره امتحان کن.')}if(response.status===404)throw Error('این آیدی پیدا نشد. املای نام کاربری گیت‌هاب را بررسی کن.');if(response.status===403||response.status===429){const reset=Number(response.headers.get('x-ratelimit-reset'));throw Error('محدودیت موقت درخواست‌های گیت‌هاب.'+(reset?' بعد از '+new Date(reset*1000).toLocaleTimeString('fa-IR')+' دوباره امتحان کن.':' چند دقیقهٔ دیگر دوباره امتحان کن.'))}if(!response.ok)throw Error('گیت‌هاب فعلاً پاسخ نمی‌دهد. دوباره امتحان کن.');return response.json()}
function analyze(user,repos){const original=repos.filter(r=>!r.fork);const counts={};original.forEach(r=>{if(r.language)counts[r.language]=(counts[r.language]||0)+1});const languages=Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));const lang=languages[0]?.[0]||null;const titles={JavaScript:['Web Developer','وب با ایده‌های تو زنده‌ست.','از ایده تا چیزی که آدم‌ها هر روز باهاش کار می‌کنن؛ تو این فاصله رو با کد پر می‌کنی.'],TypeScript:['Web Developer','برای ایده‌های بزرگ، تایپ‌های دقیق.','تو به ایده‌ها ساختار می‌دی؛ یک تایپ، یک کامپوننت و یک قدم رو به جلو.'],Python:['Python Developer','ایده‌ها، به زبان پایتون.','از ساده‌کردن کارهای تکراری تا کشف چیزهای تازه؛ کد تو شروع یک احتماله.'],Go:['Go Developer','ساده می‌نویسی. بزرگ می‌سازی.','پشت سادگی هر ابزار خوب، تصمیم‌های دقیق هست. به افتخار چیزهایی که با Go می‌سازی.'],Rust:['Rust Developer','ساختن، با دقتی از جنس Rust.','به افتخار حوصله‌ای که برای درست ساختن داری؛ حتی وقتی کامپایلر موافق نیست.'],Swift:['Apple Platforms Developer','ایده‌هایی که لمس می‌شن.','تو از خط‌های کد، تجربه‌های قابل لمس می‌سازی. همین جزئیات کوچیک دنیا رو بهتر می‌کنن.'],Kotlin:['Kotlin Developer','یک ایده، یک تجربهٔ تازه.','به افتخار تجربه‌هایی که با Kotlin خلق می‌کنی و مسئله‌هایی که براشون راه پیدا می‌کنی.'],Java:['Java Developer','پایه‌های محکم، ایده‌های بزرگ.','به افتخار پشتکاری که پشت هر پروژه‌ات هست؛ ساختن ارزش همین تلاش رو داره.']};const theme=titles[lang]||[lang?lang+' Developer':'Software Developer','داستان تو هنوز داره نوشته می‌شه.','هر پروژه از یک ایده شروع می‌شه و با کنجکاوی ادامه پیدا می‌کنه. به افتخار شوقی که برای ساختن داری.'];return {user,repos,original,languages,lang,theme,stars:original.reduce((n,r)=>n+(r.stargazers_count||0),0),top:[...original].sort((a,b)=>b.stargazers_count-a.stargazers_count)[0]}}
function log(text,percent){const p=document.createElement('p');p.textContent=text;$('logs').append(p);$('progress').style.width=percent+'%'}
async function start(value,demo=false){const username=normalize(value);if(!username){put('error','یک آیدی معتبر یا لینک پروفایل گیت‌هاب وارد کن.');$('username').focus();return}active?.abort();active=new AbortController();const controller=active;put('error','');$('intro').classList.add('hidden');$('result').classList.add('hidden');$('loading').classList.remove('hidden');$('submit').disabled=true;$('logs').replaceChildren();$('progress').style.width='0';let timedOut=false;const timeout=setTimeout(()=>{timedOut=true;controller.abort()},25000);try{log('$ connecting to @'+username+' ...',12);let user,repos=[];if(demo){user={login:'your-name',name:'Alex Developer',public_repos:24,followers:128,created_at:'2020-01-01',avatar_url:''};repos=[{name:'little-big-ideas',language:'TypeScript',stargazers_count:42,fork:false},{name:'weekend-build',language:'TypeScript',stargazers_count:16,fork:false},{name:'curiosity-lab',language:'Python',stargazers_count:8,fork:false}]}else{user=await api('/users/'+encodeURIComponent(username),controller.signal);if(user.type!=='User')throw Error('این آیدی متعلق به یک سازمان است. آیدی شخصی یک برنامه‌نویس را وارد کن.')}await pause(450);log('✓ developer found: '+(user.name||user.login),32);if(!demo){for(let page=1;page<=3;page++){const batch=await api('/users/'+encodeURIComponent(user.login)+'/repos?type=owner&sort=updated&per_page=100&page='+page,controller.signal);repos.push(...batch);if(batch.length<100)break;log('✓ '+repos.length+' public repositories received',40+page*10)}}log('✓ reading public projects & languages',72);await pause(550);current={...analyze(user,repos),demo};log('✓ appreciation compiled successfully',100);await pause(500);render();}catch(e){current=null;$('loading').classList.add('hidden');$('intro').classList.remove('hidden');put('error',timedOut?'پاسخ گیت‌هاب طول کشید. دوباره امتحان کن.':e.message);$('username').focus()}finally{clearTimeout(timeout);$('submit').disabled=false}}
function cardUrl(){const u=new URL(location.href);u.hash='';u.search='';if(!current.demo)u.searchParams.set('u',current.user.login);return u.href}
function makeQR(){const qr=qrcode(0,'M');qr.addData(cardUrl());qr.make();return qr}
function render(){const {user,languages,theme,top,demo}=current;put('greeting-name',user.name||user.login);put('name',user.name||user.login);put('handle','@'+user.login);$('handle').href=demo?'https://github.com':'https://github.com/'+encodeURIComponent(user.login);$('avatar').src=user.avatar_url||'favicon.svg';$('avatar').onerror=()=>{$('avatar').src='favicon.svg';$('avatar').onerror=null};put('role',theme[0]);put('repos-count',user.public_repos);put('stars-count',current.stars.toLocaleString('en'));put('followers-count',user.followers.toLocaleString('en'));put('member-since','BUILDING SINCE '+new Date(user.created_at).getUTCFullYear());put('story-title',theme[1]);put('personal-message',(user.name||user.login)+'، '+theme[2]+(top?' پروژهٔ «'+top.name+'» بخشی از این داستانه.':' حتی اگر هنوز پروژهٔ عمومی نداری، داستانت همین‌جا شروع می‌شه.')+' روز برنامه‌نویس مبارک! امروز یه commit هم برای خوشحال‌کردن خودت بزن.');$('languages').replaceChildren();languages.slice(0,5).forEach(([name,count])=>{const span=document.createElement('span');span.className='language';span.textContent=name+' · '+count;$('languages').append(span)});put('scope',(demo?'داده‌های نمونه':current.repos.length+' مخزن عمومی بررسی شد'+(user.public_repos>current.repos.length?'؛ حداکثر ۳۰۰ مخزن با آخرین به‌روزرسانی':''))+' • زبان‌ها بر اساس تعداد مخزن‌های غیرفورک هستند؛ ستاره‌ها مربوط به همین مخزن‌هاست. عنوان تخصص، برداشت از زبان غالب است.');$('repo-highlight').classList.toggle('hidden',!top);if(top){put('repo-highlight','↗ '+top.name+' — '+top.stargazers_count+' ستاره');$('repo-highlight').href=demo?'https://github.com':'https://github.com/'+encodeURIComponent(user.login)+'/'+encodeURIComponent(top.name)}put('branch',current.lang?current.lang.toLowerCase():'new-beginnings');$('qr').innerHTML=makeQR().createSvgTag({cellSize:2,margin:0,scalable:true});$('share').disabled=demo;put('action-status',demo?'QR نمونه به صفحهٔ ساخت کارت می‌رود.':'لینک و QR با اطلاعات عمومی روز، کارت را دوباره می‌سازند.');$('demo-banner').classList.toggle('hidden',!demo);$('loading').classList.add('hidden');$('result').classList.remove('hidden');if(!demo)history.replaceState(null,'',cardUrl());$('result').focus();celebrate()}
function celebrate(){if(reduced)return;const box=$('confetti');box.replaceChildren();for(let i=0;i<50;i++){const p=document.createElement('i');p.className='particle';p.style.left=Math.random()*100+'%';p.style.background=['#beff72','#f1f5ed','#82b6fa'][i%3];p.style.animationDelay=Math.random()*.6+'s';box.append(p)}setTimeout(()=>box.replaceChildren(),3300)}
$('lookup').addEventListener('submit',e=>{e.preventDefault();start($('username').value)});$('demo').onclick=()=>start('demo',true);$('celebrate').onclick=()=>{celebrate();put('action-status','🎉 امروز کارهای خوبت رو جشن بگیر. روزت مبارک!')};$('reset').onclick=()=>{current=null;history.replaceState(null,'',location.pathname);$('result').classList.add('hidden');$('intro').classList.remove('hidden');$('username').focus()};$('share').onclick=async()=>{try{await navigator.clipboard.writeText(cardUrl());put('action-status','لینک اختصاصی کپی شد ✓')}catch{put('action-status','لینک اختصاصی: '+cardUrl())}};$('print').onclick=()=>window.print();
$('download').onclick=async()=>{const btn=$('download');btn.disabled=true;try{await document.fonts.ready;const c=document.createElement('canvas');c.width=1000;c.height=1400;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,1000,1400);g.addColorStop(0,'#273625');g.addColorStop(1,'#101b13');x.fillStyle=g;x.fillRect(0,0,1000,1400);x.strokeStyle='#718956';x.lineWidth=3;x.strokeRect(28,28,944,1344);const text=(s,y,size=28,color='#f1f5ed',font='monospace')=>{x.fillStyle=color;x.font=size+'px '+font;x.fillText(String(s),80,y,840)};text('DEVELOPER CARD',100);text('EDITION 256 / PROGRAMMER’S DAY',150,20,'#a7bc9b');text(current.user.name||current.user.login,290,54,'#f1f5ed','Vazir, sans-serif');text('@'+current.user.login,345,30,'#a7bc9b');text(current.theme[0],410,28,'#beff72');text('HAPPY',570,96,'#f1f5ed','Arial');text('PROGRAMMER’S',680,87,'#f1f5ed','Arial');text('DAY.',805,118,'#beff72','Arial');x.fillStyle='#4d6240';x.fillRect(80,870,840,2);text(current.user.public_repos+' PUBLIC REPOS',940,29);text(current.stars+' REPO STARS  /  '+current.user.followers+' FOLLOWERS',990,26);text('BUILDING SINCE '+new Date(current.user.created_at).getUTCFullYear(),1120,24,'#a7bc9b');text('KEEP BUILDING.',1200,33,'#beff72');text('STAY CURIOUS.',1250,33,'#beff72');text(current.demo?'DEMO · FICTIONAL DATA':'STARS: ANALYZED NON-FORK REPOSITORIES',1320,17,'#a7bc9b');const qr=makeQR(),n=qr.getModuleCount(),s=Math.floor(210/(n+8)),size=(n+8)*s,left=920-size,top=1080;x.fillStyle='#fff';x.fillRect(left,top,size,size);x.fillStyle='#0b140b';for(let r=0;r<n;r++)for(let col=0;col<n;col++)if(qr.isDark(r,col))x.fillRect(left+(col+4)*s,top+(r+4)*s,s,s);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='developer-card-'+current.user.login+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);put('action-status','کارت PNG آماده شد ✓')}catch{put('action-status','دانلود انجام نشد؛ دوباره امتحان کن یا از چاپ کارت استفاده کن.')}finally{btn.disabled=false}};
